def bst_has_pair_sum(root, k):
    seen = set()
    stack = [root] if root else []
    while stack:
        node = stack.pop()
        if k - node.val in seen: return True
        seen.add(node.val)
        if node.left: stack.append(node.left)
        if node.right: stack.append(node.right)
    return False

